effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat12;
float u_xlat18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + vec2(-0.5, -0.5);
    u_xlat12 = _direction * -0.0174532942;
    u_xlat1.x = sin(u_xlat12);
    u_xlat2.x = cos(u_xlat12);
    u_xlat3.x = sin((-u_xlat12));
    u_xlat3.y = u_xlat2.x;
    u_xlat2.x = dot(u_xlat3.yx, u_xlat0.xy);
    u_xlat3.z = u_xlat1.x;
    u_xlat2.y = dot(u_xlat3.zy, u_xlat0.xy);
    u_xlat0.xy = vec2(_size, _amount) * vec2(9.5, -49.0) + vec2(0.5, 50.0);
    u_xlat0.xz = u_xlat2.xy / u_xlat0.xx;
    u_xlat0.xz = u_xlat0.xz + vec2(0.5, 0.5);
    u_xlat1 = vec4(vec4(_cur_time, _cur_time, _cur_time, _cur_time)) * vec4(_speed, _speed, _flicker, _flicker);
    u_xlat2.xyz = u_xlat1.xzw * vec3(0.100000001, -0.00300000003, 0.00200000009);
    u_xlat18 = sin(u_xlat2.x);
    u_xlat3.y = (-u_xlat18) * 0.5 + u_xlat0.x;
    u_xlat3.zw = u_xlat1.xy * vec2(0.100000001, 0.0714285746) + u_xlat0.zz;
    u_xlat3.x = u_xlat18 * 0.111111112 + u_xlat0.x;
    u_xlat1 = u_xlat3.yzxw * vec4(0.600000024, 0.600000024, 0.899999976, 0.899999976) + u_xlat2.yyzz;
    u_xlat0.x = texture(texture0, u_xlat1.xy).x;
    u_xlat12 = texture(texture0, u_xlat1.zw).z;
    u_xlat0.x = u_xlat12 * u_xlat0.x;
    u_xlat0.x = log2(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * u_xlat0.y;
    u_xlat0.x = exp2(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * _intensity;
    u_xlat0.x = u_xlat0.x * 18.0;
    u_xlat0.xyz = u_xlat0.xxx * _color.xyz;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0.w = 1.0;
    u_xlat0 = u_xlat0 + u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
